define({"topics":[{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_10.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e35753","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_9.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e35857","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_8.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e35961","topics":[]},{"title":"Removing the magnet service access vent","shortdesc":"<p class=\"shortdesc\">Removes the service access vent from the magnet enclosure allowing a ladder to stand close to the magnet on the left-hand side.<\/p>","href":"t_RemovingTheServiceAccessVent_7.html","attributes":{"data-id":"id_2002970"},"menu":{"hasChildren":false},"tocID":"id_2002970-d46e36065","topics":[]},{"title":"Removing the magnet left-hand lower rear cover","shortdesc":"<p class=\"shortdesc\">Removes the lower cover from the left-hand rear corner of the magnet.<\/p>","href":"t_RemovingTheLeftHandLowerRearCover_2.html","attributes":{"data-id":"id_2002991"},"menu":{"hasChildren":false},"tocID":"id_2002991-d46e36169","topics":[]},{"title":"Removing the magnet upper service access panel","shortdesc":"<p class=\"shortdesc\">Removes the upper service access panel allowing access to components mounted on top of the magnet.<\/p>","href":"t_RemovingTheUpperServiceAccessPanel_5.html","attributes":{"data-id":"id_2002968"},"menu":{"hasChildren":false},"tocID":"id_2002968-d46e36273","topics":[]},{"title":"Removing the magnet rear trim ring","shortdesc":"<p class=\"shortdesc\">Removes the rear trim ring from the rear endbell.  The trim ring covers the bolts securing the magnet rear enclosures.<\/p>","href":"t_RemovingTheRearTrimRing_9.html","attributes":{"data-id":"id_2002972"},"menu":{"hasChildren":false},"tocID":"id_2002972-d46e36377","topics":[]},{"title":"Removing the magnet rear cable cover","shortdesc":"<p class=\"shortdesc\">Removes the rear cable cover from the magnet enclosure.<\/p>","href":"t_RemovingTheRearCableCover_8.html","attributes":{"data-id":"id_2002978"},"menu":{"hasChildren":false},"tocID":"id_2002978-d46e36481","topics":[]},{"title":"Removing the magnet rear cable cover bracket","shortdesc":"<p class=\"shortdesc\">Removes the bracket on which the rear cable cover hangs from the magnet.<\/p>","href":"t_RemovingTheMagnetRearCableCoverBracket_4.html","attributes":{"data-id":"id_2004491"},"menu":{"hasChildren":false},"tocID":"id_2004491-d46e36585","topics":[]},{"title":"Removing the magnet left-hand upper rear cover","shortdesc":"<p class=\"shortdesc\">Removes the upper cover from the left-hand rear corner of the magnet.<\/p>","href":"t_RemovingTheLeftHandUpperRearCover.html","attributes":{"data-id":"id_2002993"},"menu":{"hasChildren":false},"tocID":"id_2002993-d46e36689","topics":[]}]});